head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > M > initCheckCombobox]<br/>컴포넌트의 아이템 정의를 초기화합니다.",
    "validation" : [                
        "아이템이 GridViewItemSet 으로 정의된 경우 DataCollection 에 반영되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {

}



scwin.btn_getSelectedInfo_onclick = function (e) {
    let rtn = target1.getSelectedInfo();

    // 배열의 각 요소를 순회합니다.
    for (let i = 0; i < rtn.length; i++) {
        let item = rtn[i]; // 현재 요소를 가져옵니다.

        // index, label, value, checked 값을 가져옵니다.
        let index = item.index;
        let label = item.label;
        let value = item.value;
        let checked = item.checked;

        // 원하는 작업을 수행할 수 있습니다.
        wf_body_bottom.getObj("scwin").setReturnValue("Index:"+index+", Label:"+label+", Value:"+value+ ", Checked:"+checked);
    }    
};



scwin.btn_getInfoArray_onclick = function (e) {
    let rtn = target1.getInfoArray();
    wf_body_bottom.getObj("scwin").setReturnValue("objArray:" +rtn);

    if (rtn) {
        rtn.forEach(function(item, index) {
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 index : " +item.index);
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 label : " +item.label);
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 value : " +item.value);
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 checked : " +item.checked);
        });          
    }
};



scwin.btn_initCheckCombobox_onclick = function (e) {
	target1.initCheckCombobox();
};



scwin.btn_getDataList_onclick = function (e) {
	let rsData  = dlt_gridviewItem.getAllJSON();

    for(var i = 0; i < rsData.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("value 값 : " + rsData[i].value);
    }
};
